}

a:hover {
    color: var(--text-secondary);
}

ul {
    list-style: none;
}

/* Accessibility Utilities */
.skip-link {
    position: absolute;
    top: -50px;
    left: 0;
    background: var(--surface-color);
    color: var(--text-primary);
    padding: 12px 24px;
    z-index: 100;
    transition: top 0.2s;
    font-weight: 600;
}

.skip-link:focus {
    top: 0;
}

.sr-only {
    position: absolute;
    width: 1px;
