}

/* Deals Section */
.deals-section {
    background-color: var(--surface-color);
    padding: 6rem 24px;
    text-align: center;
    border-top: 1px solid var(--border-color);
    border-bottom: 1px solid var(--border-color);
}

.deals-content {
    max-width: 600px;
