    margin-bottom: 0.5rem;
    font-weight: 600;
}

.editorial-heading {
    font-size: 1.5rem;
    margin-bottom: 1rem;
    line-height: 1.3;
}

.editorial-content p {
    color: var(--text-secondary);
    margin-bottom: 1.5rem;
}

.read-more {
    font-weight: 600;
    text-transform: uppercase;
    font-size: 0.9rem;
    letter-spacing: 0.05em;
    display: inline-flex;
    align-items: center;
    gap: 0.5rem;
}

.read-more span {
    transition: transform 0.2s ease;
}

.read-more:hover span {
    transform: translateX(4px);
