document.addEventListener('DOMContentLoaded', () => {
    // Mobile Navigation Toggle
    const menuToggle = document.querySelector('.mobile-menu-toggle');
    const mainNav = document.getElementById('main-nav');

    if (menuToggle && mainNav) {
        menuToggle.addEventListener('click', () => {
            const isExpanded = menuToggle.getAttribute('aria-expanded') === 'true';
            menuToggle.setAttribute('aria-expanded', !isExpanded);
            mainNav.classList.toggle('is-open');
        });
    }

    // Interactive Add to Cart buttons (mock functionality)
    const quickAddButtons = document.querySelectorAll('.btn-quick-add');

    quickAddButtons.forEach(button => {
        button.addEventListener('click', function(e) {
            e.preventDefault(); // prevent triggering the card's main link since the button is visually positioned over it
            e.stopPropagation();

            const originalText = this.textContent;
            this.textContent = 'Added!';
            this.style.backgroundColor = '#4caf50'; // Accessible green for success
            this.style.color = 'white';

            // Announce to screen readers using ARIA live region
            const announcement = document.createElement('div');
            announcement.setAttribute('aria-live', 'polite');
            announcement.classList.add('sr-only');
            announcement.textContent = 'Item added to cart';
            document.body.appendChild(announcement);

            setTimeout(() => {
                this.textContent = originalText;
                this.style.backgroundColor = '';
                this.style.color = '';
                document.body.removeChild(announcement);
            }, 2000);
        });
    });

    // Handle newsletter submission (mock functionality)
    const newsletterForm = document.querySelector('.newsletter-form');
    if (newsletterForm) {
        newsletterForm.addEventListener('submit', (e) => {
            e.preventDefault();
            const input = newsletterForm.querySelector('input');
            const btn = newsletterForm.querySelector('button');
            const originalPlaceholder = input.placeholder;
            const originalBtnText = btn.textContent;

            input.value = '';
            input.placeholder = 'Thanks for subscribing!';
            btn.textContent = 'Subscribed';
            btn.disabled = true;

            // Screen reader announcement
            const announcement = document.createElement('div');
            announcement.setAttribute('aria-live', 'polite');
            announcement.classList.add('sr-only');
            announcement.textContent = 'Successfully subscribed to the newsletter';
            document.body.appendChild(announcement);

            setTimeout(() => {
                input.placeholder = originalPlaceholder;
                btn.textContent = originalBtnText;
                btn.disabled = false;
                document.body.removeChild(announcement);
            }, 3000);
        });
    }
});

